using System.Collections.Generic; using System.Data; using System.Linq; using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp { public partial class ContactPage : BasePage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetContactDetails() { var table = DbHelper.ExecuteDataTable("SELECT SettingKey, SettingValue FROM SystemSettings WHERE SettingKey IN ('WhatsAppNumber','SupportPhone','SupportEmail','FacebookUrl','TikTokUrl','OfficeLocation')", CommandType.Text); var values = DbHelper.ToDictionaryList(table).ToDictionary(x => x["SettingKey"].ToString(), x => x["SettingValue"] == null ? string.Empty : x["SettingValue"].ToString(), System.StringComparer.OrdinalIgnoreCase); var phone = values.ContainsKey("SupportPhone") ? values["SupportPhone"] : string.Empty; var whatsApp = values.ContainsKey("WhatsAppNumber") ? values["WhatsAppNumber"] : string.Empty; var email = values.ContainsKey("SupportEmail") ? values["SupportEmail"] : string.Empty; var facebook = values.ContainsKey("FacebookUrl") ? values["FacebookUrl"] : string.Empty; var tikTok = values.ContainsKey("TikTokUrl") ? values["TikTokUrl"] : string.Empty; var location = values.ContainsKey("OfficeLocation") ? values["OfficeLocation"] : string.Empty; var items = new List<object> { new { Label = "WhatsApp", Value = whatsApp, Url = "https://wa.me/" + whatsApp }, new { Label = "Call WAMO", Value = phone, Url = "tel:" + phone }, new { Label = "Facebook", Value = facebook, Url = facebook }, new { Label = "TikTok", Value = tikTok, Url = tikTok }, new { Label = "Email", Value = email, Url = "mailto:" + email }, new { Label = "Location", Value = location, Url = "https://maps.google.com/?q=" + System.Uri.EscapeDataString(location) } }; return new { success = true, data = items }; } } }
